function piBookingEnsureDisplay() {
  if (!process.env.DISPLAY) process.env.DISPLAY = ':99';
  try {
    const fsD = require('fs');
    const n = String(process.env.DISPLAY).replace(/^:/, '').split('.')[0];
    if (fsD.existsSync('/tmp/.X11-unix/X' + n)) return;
    const { spawn, spawnSync } = require('child_process');
    const child = spawn('Xvfb', [process.env.DISPLAY, '-screen', '0', '1920x1080x24', '-ac'], { detached: true, stdio: 'ignore' });
    child.on('error', function () {});
    child.unref();
    spawnSync('sleep', ['0.5']);
  } catch (eXvfb) {}
}
